// ═══ LockSupport.park()/unpark() — permit-based ═══
Thread worker = new Thread(() -> {
    System.out.println("Before park");
    LockSupport.park();  // blocks until permit available (or already available!)
    System.out.println("After park — resumed!");
});
worker.start();
Thread.sleep(100);
LockSupport.unpark(worker);  // sets permit → worker resumes!

// ═══ unpark BEFORE park — NOT lost! ═══
Thread t = new Thread(() -> {
    try { Thread.sleep(200); } catch (InterruptedException e) { }
    LockSupport.park();  // permit already set by main thread → returns IMMEDIATELY!
    System.out.println("Didn't block! Permit was waiting.");
});
t.start();
LockSupport.unpark(t);  // set permit BEFORE park()!
// When t calls park(): permit = 1 → consume → return immediately! Not blocked!

// ═══ wait/notify — notify before wait IS lost! ═══
Object lock = new Object();
// Thread-1:
synchronized (lock) { lock.notify(); }  // notify — nobody waiting! LOST!
// Thread-2:
synchronized (lock) { lock.wait(); }    // waits FOREVER! The notify was lost!

// ═══ COMPARISON ═══
// Feature              park/unpark              wait/notify
// Lock required?       NO                       YES (synchronized)
// Signal before wait?  NOT lost (permit)        LOST!
// Target thread        unpark(specificThread)   notify() wakes ANY one
// Spurious wakeup?     YES (must check cond.)   YES
// Used by              AQS, ReentrantLock       Classic monitor pattern
// IllegalMonitorState? NEVER                    If not in synchronized!

// ═══ WHY AQS USES park/unpark ═══
// AbstractQueuedSynchronizer (basis of ReentrantLock, Semaphore, etc.):
// Thread fails to acquire → added to CLH queue → LockSupport.park()
// Lock released → next thread in queue → LockSupport.unpark(next)
// No monitor needed! unpark targets SPECIFIC thread! Signal not lost!
