package com.bank.park;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class ParkUnparkTest {

    // ═══ park/unpark: basic blocking/unblocking ═══
    @Test
    void parkUnpark_basic() throws InterruptedException {
        boolean[] resumed = {false};
        Thread worker = new Thread(() -> {
            LockSupport.park();  // blocks until unpark!
            resumed[0] = true;
        });
        worker.start();
        Thread.sleep(100);
        assertThat(resumed[0]).isFalse();  // still parked!

        LockSupport.unpark(worker);  // resume!
        worker.join(2000);
        assertThat(resumed[0]).isTrue();  // resumed!
    }

    // ═══ unpark BEFORE park — NOT lost! ═══
    @Test
    void unparkBeforePark_notLost() throws InterruptedException {
        Thread worker = new Thread(() -> {
            try { Thread.sleep(200); } catch (InterruptedException e) { }
            long start = System.currentTimeMillis();
            LockSupport.park();  // permit already set → returns IMMEDIATELY!
            long elapsed = System.currentTimeMillis() - start;
            assertThat(elapsed).isLessThan(50);  // didn't block!
        });
        worker.start();
        LockSupport.unpark(worker);  // BEFORE park()!
        worker.join(5000);
    }

    // ═══ notify before wait — IS LOST! ═══
    @Test
    void notifyBeforeWait_isLost() throws InterruptedException {
        Object lock = new Object();
        boolean[] stuck = {true};

        // Notify first (nobody waiting):
        synchronized (lock) { lock.notify(); }  // LOST!

        Thread waiter = new Thread(() -> {
            synchronized (lock) {
                try { lock.wait(1000); } catch (InterruptedException e) { }
                stuck[0] = false;
            }
        });
        waiter.start();
        waiter.join(3000);
        // waiter had to wait the full 1000ms timeout because notify was lost!
    }

    // ═══ park doesn't need synchronized ═══
    @Test
    void park_noSynchronizedNeeded() throws InterruptedException {
        boolean[] parked = {false};
        Thread t = new Thread(() -> {
            parked[0] = true;
            LockSupport.park();  // no synchronized! No IllegalMonitorStateException!
        });
        t.start();
        Thread.sleep(100);
        assertThat(t.getState()).isEqualTo(Thread.State.WAITING);
        LockSupport.unpark(t);
        t.join();
    }
}
